func (t *IfInstruction) CompareTo(o any) int {
	ao := o.(Instruction)
	if ao == Instruction(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*IfInstruction)
	if c := t.Condition.CompareTo(tco.Condition); c != 0 {
		return c
	}
	if c := t.SuccesInst.CompareTo(tco.SuccesInst); c != 0 {
		return c
	}
	if c := t.FailureInst.CompareTo(tco.FailureInst); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

func (t *IfInstruction) CompareToLPO(o any) int {
	ao := o.(Instruction)
	if ao == Instruction(t) {
		return 0
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*IfInstruction)
	if c := t.Condition.CompareToLPO(tco.Condition); c != 0 {
		return c
	}
	if c := t.SuccesInst.CompareToLPO(tco.SuccesInst); c != 0 {
		return c
	}
	if c := t.FailureInst.CompareToLPO(tco.FailureInst); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

// ToATerm is the ATerm of the term: an application of If.
func (t *IfInstruction) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	return f.MakeAppl(f.MakeAFun("If", 3, false), t.Condition.ToATerm(), t.SuccesInst.ToATerm(), t.FailureInst.ToATerm())
}

// fromTermIfInstruction is Java Gom's If.fromTerm: an unquoted application of
// If whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermIfInstruction(trm aterm.ATerm, conv aterm.ATermConverter) (Instruction, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "If" && !appl.GetAFun().IsQuoted() {
		return MakeIf(ExpressionFromTermConv(appl.GetArgument(0), conv), InstructionFromTermConv(appl.GetArgument(1), conv), InstructionFromTermConv(appl.GetArgument(2), conv)), true
	}
	return nil, false
}

