// fromTermAssignInstruction is Java Gom's Assign.fromTerm: an unquoted application of
// Assign whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermAssignInstruction(trm aterm.ATerm, conv aterm.ATermConverter) (Instruction, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "Assign" && !appl.GetAFun().IsQuoted() {
		return MakeAssign(BQTermFromTermConv(appl.GetArgument(0), conv), ExpressionFromTermConv(appl.GetArgument(1), conv)), true
	}
	return nil, false
}

