func (t *ReturnInstruction) CompareTo(o any) int {
	ao := o.(Instruction)
	if ao == Instruction(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*ReturnInstruction)
	if c := t.Kid1.CompareTo(tco.Kid1); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

func (t *ReturnInstruction) CompareToLPO(o any) int {
	ao := o.(Instruction)
	if ao == Instruction(t) {
		return 0
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*ReturnInstruction)
	if c := t.Kid1.CompareToLPO(tco.Kid1); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

// ToATerm is the ATerm of the term: an application of Return.
func (t *ReturnInstruction) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	return f.MakeAppl(f.MakeAFun("Return", 1, false), t.Kid1.ToATerm())
}

// fromTermReturnInstruction is Java Gom's Return.fromTerm: an unquoted application of
// Return whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermReturnInstruction(trm aterm.ATerm, conv aterm.ATermConverter) (Instruction, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "Return" && !appl.GetAFun().IsQuoted() {
		return MakeReturn(BQTermFromTermConv(appl.GetArgument(0), conv)), true
	}
	return nil, false
}

