// checked: a missing argument is an index out of range).
func fromTermAbstractBlockInstruction(trm aterm.ATerm, conv aterm.ATermConverter) (Instruction, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "AbstractBlock" && !appl.GetAFun().IsQuoted() {
		return MakeAbstractBlock(InstructionListFromTermConv(appl.GetArgument(0), conv)), true
	}
	return nil, false
}

