func (t *CompiledMatchInstruction) CompareTo(o any) int {
	ao := o.(Instruction)
	if ao == Instruction(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*CompiledMatchInstruction)
	if c := t.AutomataInst.CompareTo(tco.AutomataInst); c != 0 {
		return c
	}
	if c := t.Options.CompareTo(tco.Options); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

func (t *CompiledMatchInstruction) CompareToLPO(o any) int {
	ao := o.(Instruction)
	if ao == Instruction(t) {
		return 0
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*CompiledMatchInstruction)
	if c := t.AutomataInst.CompareToLPO(tco.AutomataInst); c != 0 {
		return c
	}
	if c := t.Options.CompareToLPO(tco.Options); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

// ToATerm is the ATerm of the term: an application of CompiledMatch.
func (t *CompiledMatchInstruction) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	return f.MakeAppl(f.MakeAFun("CompiledMatch", 2, false), t.AutomataInst.ToATerm(), t.Options.ToATerm())
}

// fromTermCompiledMatchInstruction is Java Gom's CompiledMatch.fromTerm: an unquoted application of
// CompiledMatch whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermCompiledMatchInstruction(trm aterm.ATerm, conv aterm.ATermConverter) (Instruction, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "CompiledMatch" && !appl.GetAFun().IsQuoted() {
		return MakeCompiledMatch(InstructionFromTermConv(appl.GetArgument(0), conv), OptionListFromTermConv(appl.GetArgument(1), conv)), true
	}
	return nil, false
}

