// elements returns the cached Visitable children of the list: its
// elements (Java's getChildren, i.e. toArray).
// Java's getChildren is the typed toArray(new RuleInstruction[]{}): a last tail
// that is not a list (of sort RuleInstructionList) cannot be stored in it
// (ArrayStoreException, a *aterm.GomError here).
func (t *ConcRuleInstructionRuleInstructionList) elements() []any {
	if c := t.children.Load(); c != nil {
		return *c
	}
	var cur RuleInstructionList = t
	for {
		c, ok := cur.(*ConcRuleInstructionRuleInstructionList)
		if !ok || c.empty {
			break
		}
		cur = c.tail
	}
	if c, ok := cur.(*ConcRuleInstructionRuleInstructionList); !ok || !c.empty {
		panic(&aterm.GomError{Msg: fmt.Sprintf("ArrayStoreException: the tail %v of a concRuleInstruction list is not a RuleInstruction", cur)})
	}
	c := t.ToArray()
	t.children.Store(&c)
	return c
}

