// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
// ClassCastException).
func (t *ConcRuleInstructionRuleInstructionList) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	var heads []RuleInstruction
	var cur RuleInstructionList = t
	for {
		c, ok := cur.(*ConcRuleInstructionRuleInstructionList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	l := f.MakeListEmpty()
	if c, ok := cur.(*ConcRuleInstructionRuleInstructionList); !ok || !c.empty {
		tl, isList := cur.ToATerm().(*aterm.ATermList)
		if !isList {
			panic(&aterm.GomError{Msg: fmt.Sprintf("ClassCastException: the ATerm of %v is not an ATermList", cur)})
		}
		l = tl
	}
	for i := len(heads) - 1; i >= 0; i-- {
		l = f.MakeList(heads[i].ToATerm(), l)
	}
	return l
}

// fromTermConcRuleInstructionRuleInstructionList is Java Gom's concRuleInstruction.fromTerm: an application of concRuleInstruction, or a
// list (of ToATerm), of convertible elements.
func fromTermConcRuleInstructionRuleInstructionList(trm aterm.ATerm, conv aterm.ATermConverter) (res RuleInstructionList, ok bool) {
	trm = conv.Convert(trm)
	if appl, isAppl := trm.(*aterm.ATermAppl); isAppl && appl.GetName() == "concRuleInstruction" {
		elems := make([]RuleInstruction, appl.GetArity())
		for i, a := range appl.GetArguments() {
			elems[i] = RuleInstructionFromTermConv(a, conv)
		}
		return MakeConcRuleInstruction(elems...), true
	}
	if list, isList := trm.(*aterm.ATermList); isList {
		// an element that cannot be converted: not a concRuleInstruction (Java returns null)
		defer func() {
			if recover() != nil {
				res, ok = nil, false
			}
		}()
		var elems []RuleInstruction
		for !list.IsEmpty() {
			elems = append(elems, RuleInstructionFromTermConv(list.GetFirst(), conv))
			list = list.GetNext()
		}
		return MakeConcRuleInstruction(elems...), true
	}
	return nil, false
}

